@SpringBootTest
@AutoConfigureMockMvc
class UserControllerMvcTest {

    @Autowired
    private MockMvc mockMvc;

    @Test
    void shouldGetUserViaMockMvc() throws Exception {
        mockMvc.perform(get("/api/users/{id}", 1L)
                .accept(MediaType.APPLICATION_JSON))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.username", is("janedoe")));
    }
}

@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
class UserControllerWebTestClientIntegrationTest {

    @Autowired
    private WebTestClient webTestClient;

    @Test
    void shouldGetUserViaWebTestClient() {
        webTestClient.get().uri("/api/users/{id}", 1L)
                .accept(MediaType.APPLICATION_JSON)
                .exchange()
                .expectStatus().isOk()
                .expectBody()
                .jsonPath("$.username").isEqualTo("janedoe");
    }
}
